input.command:
$ErrorActionPreference = 'Stop'
$LAB = 'C:\Users\nolan\constitutional-integration-lab'
$csv = Import-Csv "$LAB\temporary\crx_raw_inventory.csv"

function Get-CrxMeta($row) {
  $p = $row.Path.ToLower()
  $runtime = $false; $replay = $false; $lineage = $false
  $resp = 'reference'; $status = 'REFERENCE'
  if ($p -match 'runtime\\kernel\\commit-service\\src\\') {
    $runtime = $true
    switch -Regex ($p) {
      'canonical_engine' { $resp='canonicalization'; $replay=$true; $status='CRITICAL' }
      'identity_engine' { $resp='identity'; $replay=$true; $status='CRITICAL' }
      'dag_validator' { $resp='lineage validation'; $replay=$true; $lineage=$true; $status='CRITICAL' }
      'lineage_store' { $resp='lineage persistence'; $replay=$true; $lineage=$true; $status='HIGH' }
      'artifact_store|db\.ts|ledger_schema' { $resp='persistence'; $replay=$true; $lineage=$true; $status='HIGH' }
      'event_log' { $resp='event recording'; $replay=$true; $status='HIGH' }
      'commit_controller|server\.ts' { $resp='orchestration/transport'; $replay=$true; $lineage=$true; $status='HIGH' }
      'audit_controller|logger' { $resp='observability'; $status='MEDIUM' }
      default { $resp='runtime'; $status='HIGH' }
    }
  } elseif ($p -match 'replay|reconstruction|deterministic') { $replay=$true; $resp='replay specification'; $status='HIGH' }
  elseif ($p -match 'lineage|dag|graph|ancestry') { $lineage=$true; $resp='lineage specification'; $status='HIGH' }
  elseif ($p -match 'claim\.schema|decision\.schema|constitutional-state|invariant\.schema|canonical-event|foundational-primitives|audit-event|argument-graph') { $resp='constitutional schema'; $replay=$true; $lineage=$true; $status='CRITICAL' }
  elseif ($p -match 'inventory\.json') { $resp='lineage inventory'; $lineage=$true; $status='HIGH' }
  elseif ($p -match 'crx_workspace_indexer') { $resp='workspace graph tooling'; $lineage=$true; $status='HIGH' }
  elseif ($p -match 'agent\.md|ucia-constitution|constitution\.md') { $resp='constitutional law'; $status='CRITICAL' }
  elseif ($p -match 'docker-compose|dockerfile') { $resp='infrastructure scaffold'; $status='PARTIAL' }
  elseif ($p -match '_report\.md|file_inventory|provenance|verified_') { $resp='audit artifact'; $status='REFERENCE' }
  elseif ($p -match 'replay-engine|event-store|persistent-cognition-graph') { $resp='diagram metadata'; $replay=$true; $lineage=$true; $status='REFERENCE' }
  elseif ($p -match 'node_modules') { $status='DEAD' }
  [PSCustomObject]@{Runtime=$runtime; Replay=$replay; Lineage=$lineage; Responsibility=$resp; Status=$status}
}

$out = @()
foreach ($r in $csv) {
  $m = Get-CrxMeta $r
  $out += [PSCustomObject]@{
    File = Split-Path $r.Path -Leaf
    Path = $r.Path
    Type = $r.Type
    Size = $r.Size
    Responsibility = $m.Responsibility
    RuntimeRelevant = if ($m.Runtime) {'YES'} else {'NO'}
    ReplayRelevant = if ($m.Replay) {'YES'} else {'NO'}
    LineageRelevant = if ($m.Lineage) {'YES'} else {'NO'}
    Status = $m.Status
    Modified = $r.Modified
  }
}
$out | Export-Csv "$LAB\temporary\crx_classified.csv" -NoTypeInformation
Write-Output "Classified $($out.Count) CRX files"

